CONFIRMATION=''
r=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review')
assert r.is_dir() and not r.is_symlink()
sys.path.insert(0,str(r/'tools'))
from stage5_board_readonly_inventory import fingerprint
from stage5_03_voice_run import discover_audio,devices,query
p=r/'reports/stage5_03_board/final_state';p.mkdir()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(name,value):(p/name).write_text(json.dumps(value,indent=2)+'\n')
original_before=json.loads((r/'reports/stage5_03_board/original_before.json').read_text());original_after=fingerprint();save('original_after.json',original_after)
accepted=json.loads((r/'reports/stage5_03_board/accepted_binaries_before.json').read_text());accepted_after={name:sha(r/name) for name in accepted};save('accepted_binaries_after.json',accepted_after)
old_source=json.loads((r/'reports/stage5_02_board/final_state_v2/source_sha256.json').read_text())
checks={
'original_321_unchanged':original_before==original_after,
'accepted_binaries_unchanged':accepted==accepted_after,
'root_5_2_sources_unchanged':all(sha(r/name)==digest for name,digest in old_source.items()),
'baseline_instrumented_sources_unchanged':all(sha(r/'stage5_03_baseline_source'/name)==digest for name,digest in BASELINE.items()),
'candidate_sources_match_local':all(sha(r/'stage5_03_source'/name)==digest for name,digest in EXPECTED.items())}
save('source_sha256.json',EXPECTED);save('baseline_source_sha256.json',BASELINE)
audio=discover_audio();post=devices(audio);save('devices.json',post)
rga=query(['sudo','-n','--','/usr/bin/fuser','-v','/dev/rga']);save('rga_device.json',rga)
checks['devices_released']=post['clear'];checks['rga_released']=rga['exit_code']==1 and not rga['stdout'].strip() and not rga['stderr'].strip()
checks['original_files_checked']=len(original_after);checks['accepted_root_sources_checked']=len(old_source);checks['candidate_sources_checked']=len(EXPECTED)
checks['disk_free_bytes']=shutil.disk_usage(r).free
save('memory.json',query(['free','-b']));save('disk.json',query(['df','-B1',str(r)]));save('dmesg.json',query(['dmesg','--ctime']))
checks['models_not_copied_to_stage5_03_sources']=not (r/'stage5_03_source/models').exists()
(p/'user_confirmations.json').write_bytes(base64.b64decode(CONFIRMATION))
save('result.json',checks);print('FINAL_STATE',json.dumps(checks),flush=True)
assert all(v for k,v in checks.items() if isinstance(v,bool)),checks
assert checks['disk_free_bytes']>=500*1024**2
